:On Error exit
SET NOCOUNT ON;
SET XACT_ABORT OFF;
IF OBJECT_ID(N'tempdb..#Upgrade20Rows') IS NULL THROW 54922,N'Der vollständige Originalsnapshot fehlt.',1;
IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'Toolbelt.Module.toolbelt.core.work-queue.Version' AND CONVERT(nvarchar(64),value)=N'2.1.0') THROW 54922,N'Queue2.1 wurde nicht installiert.',2;
IF EXISTS(SELECT [WorkItemId],[WorkTypeId],[PayloadJson],[Status],[EnqueuedAtUtc],[EnqueuedBy],[ClaimedAtUtc],[ClaimedBy],[ClaimToken],[ClaimGeneration],[LeaseDurationSeconds],[LeaseUntilUtc],[LastHeartbeatAtUtc],[RecoveryCount],[LastRecoveredAtUtc],[LastRecoveredBy],[CompletedAtUtc],[CompletedBy],[FailedAtUtc],[FailedBy],[FailureCode],[FailureMessage],[RowVersion],[ExecutionGroup],[Priority],[ExecutionMode],[IdempotencyKey],[MaxAttempts],[RetryBaseDelaySeconds],[RetryMaxDelaySeconds],[RetryCycleNumber],[CycleAttemptCount],[NextAttemptAtUtc],[LastErrorCode],[LastErrorMessage],[LastRetryScheduledAtUtc],[LastRetryScheduledBy],[DeadLetteredAtUtc],[DeadLetteredBy],[LastRequeuedAtUtc],[LastRequeuedBy],[LastRequeueReason],[BarrierEpoch] FROM #Upgrade20Rows EXCEPT SELECT [WorkItemId],[WorkTypeId],[PayloadJson],[Status],[EnqueuedAtUtc],[EnqueuedBy],[ClaimedAtUtc],[ClaimedBy],[ClaimToken],[ClaimGeneration],[LeaseDurationSeconds],[LeaseUntilUtc],[LastHeartbeatAtUtc],[RecoveryCount],[LastRecoveredAtUtc],[LastRecoveredBy],[CompletedAtUtc],[CompletedBy],[FailedAtUtc],[FailedBy],[FailureCode],[FailureMessage],[RowVersion],[ExecutionGroup],[Priority],[ExecutionMode],[IdempotencyKey],[MaxAttempts],[RetryBaseDelaySeconds],[RetryMaxDelaySeconds],[RetryCycleNumber],[CycleAttemptCount],[NextAttemptAtUtc],[LastErrorCode],[LastErrorMessage],[LastRetryScheduledAtUtc],[LastRetryScheduledBy],[DeadLetteredAtUtc],[DeadLetteredBy],[LastRequeuedAtUtc],[LastRequeuedBy],[LastRequeueReason],[BarrierEpoch] FROM toolbelt_core.WorkItem) OR EXISTS(SELECT [WorkItemId],[WorkTypeId],[PayloadJson],[Status],[EnqueuedAtUtc],[EnqueuedBy],[ClaimedAtUtc],[ClaimedBy],[ClaimToken],[ClaimGeneration],[LeaseDurationSeconds],[LeaseUntilUtc],[LastHeartbeatAtUtc],[RecoveryCount],[LastRecoveredAtUtc],[LastRecoveredBy],[CompletedAtUtc],[CompletedBy],[FailedAtUtc],[FailedBy],[FailureCode],[FailureMessage],[RowVersion],[ExecutionGroup],[Priority],[ExecutionMode],[IdempotencyKey],[MaxAttempts],[RetryBaseDelaySeconds],[RetryMaxDelaySeconds],[RetryCycleNumber],[CycleAttemptCount],[NextAttemptAtUtc],[LastErrorCode],[LastErrorMessage],[LastRetryScheduledAtUtc],[LastRetryScheduledBy],[DeadLetteredAtUtc],[DeadLetteredBy],[LastRequeuedAtUtc],[LastRequeuedBy],[LastRequeueReason],[BarrierEpoch] FROM toolbelt_core.WorkItem EXCEPT SELECT [WorkItemId],[WorkTypeId],[PayloadJson],[Status],[EnqueuedAtUtc],[EnqueuedBy],[ClaimedAtUtc],[ClaimedBy],[ClaimToken],[ClaimGeneration],[LeaseDurationSeconds],[LeaseUntilUtc],[LastHeartbeatAtUtc],[RecoveryCount],[LastRecoveredAtUtc],[LastRecoveredBy],[CompletedAtUtc],[CompletedBy],[FailedAtUtc],[FailedBy],[FailureCode],[FailureMessage],[RowVersion],[ExecutionGroup],[Priority],[ExecutionMode],[IdempotencyKey],[MaxAttempts],[RetryBaseDelaySeconds],[RetryMaxDelaySeconds],[RetryCycleNumber],[CycleAttemptCount],[NextAttemptAtUtc],[LastErrorCode],[LastErrorMessage],[LastRetryScheduledAtUtc],[LastRetryScheduledBy],[DeadLetteredAtUtc],[DeadLetteredBy],[LastRequeuedAtUtc],[LastRequeuedBy],[LastRequeueReason],[BarrierEpoch] FROM #Upgrade20Rows) THROW 54923,N'Legacydaten, Unicodepayload, Rowversion, Tokens oder History wurden verändert.',1;
IF (SELECT COUNT(*) FROM #Upgrade20Identity)<>1 OR IDENT_CURRENT(N'toolbelt_core.WorkItem') IS NULL OR IDENT_SEED(N'toolbelt_core.WorkItem') IS NULL OR IDENT_INCR(N'toolbelt_core.WorkItem') IS NULL OR EXISTS(SELECT 1 FROM #Upgrade20Identity WHERE IdentityCurrent IS NULL OR IdentitySeed IS NULL OR IdentityIncrement IS NULL OR IdentityCurrent<>IDENT_CURRENT(N'toolbelt_core.WorkItem') OR IdentitySeed<>IDENT_SEED(N'toolbelt_core.WorkItem') OR IdentityIncrement<>IDENT_INCR(N'toolbelt_core.WorkItem')) THROW 54923,N'Identitymetadaten wurden verändert.',2;
IF EXISTS(SELECT 1 FROM toolbelt_core.WorkItem WHERE ManagedReservationId IS NOT NULL OR ManagedHold<>0 OR ManagedCompletionNonce IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM toolbelt_core.WorkQueueManagedGate WHERE GateId=1 AND ManagedEnabled=0 AND PendingReservationId IS NULL) THROW 54924,N'Neutrale Manageddefaults fehlen.',1;
DECLARE @ActiveId bigint,@ActiveToken uniqueidentifier,@ActiveGeneration bigint;
SELECT @ActiveId=WorkItemId,@ActiveToken=ClaimToken,@ActiveGeneration=ClaimGeneration FROM #Upgrade20Rows WHERE Status='CLAIMED';
EXEC toolbelt_core.USP_CompleteWork @WorkItemId=@ActiveId,@ClaimToken=@ActiveToken,@ResultTable=N'#Upgrade20Status';
IF NOT EXISTS(SELECT 1 FROM toolbelt_core.WorkItem WHERE WorkItemId=@ActiveId AND ClaimToken=@ActiveToken AND ClaimGeneration=@ActiveGeneration AND Status='COMPLETED') THROW 54925,N'Der ursprüngliche aktive Claim konnte nicht abgeschlossen werden.',1;
EXEC toolbelt_core.USP_ClaimWork @ResultTable=N'#Upgrade20Claim';
IF (SELECT COUNT(*) FROM #Upgrade20Claim)<>1 OR NOT EXISTS(SELECT 1 FROM #Upgrade20Claim c JOIN #Upgrade20Rows old ON old.WorkItemId=c.WorkItemId AND old.Status='QUEUED') THROW 54926,N'Legacyadmission nach Upgrade ist inkonsistent.',1;
DECLARE @ClaimObjectId int=OBJECT_ID(N'tempdb..#Upgrade20Claim');
CREATE TABLE #Upgrade20ExpectedClaim(Ordinal int,Name sysname COLLATE Latin1_General_100_BIN2,TypeId tinyint,MaxLength smallint,Scale tinyint,Nullable bit);
INSERT #Upgrade20ExpectedClaim VALUES(1,N'WorkItemId',127,8,0,0),(2,N'WorkTypeName',167,128,0,0),(3,N'PayloadJson',231,-1,0,1),(4,N'ClaimToken',36,16,0,0),(5,N'ClaimedAtUtc',42,8,7,0),(6,N'ClaimGeneration',127,8,0,0),(7,N'LeaseUntilUtc',42,8,7,0),(8,N'LastHeartbeatAtUtc',42,8,7,0);
IF (SELECT COUNT(*) FROM tempdb.sys.columns WHERE object_id=@ClaimObjectId)<>8 OR EXISTS(SELECT 1 FROM #Upgrade20ExpectedClaim expected LEFT JOIN (SELECT ROW_NUMBER() OVER(ORDER BY column_id) OutputOrdinal,name,column_id,system_type_id,user_type_id,max_length,scale,is_nullable,collation_name FROM tempdb.sys.columns WHERE object_id=@ClaimObjectId) actual ON actual.OutputOrdinal=expected.Ordinal AND actual.name COLLATE Latin1_General_100_BIN2=expected.Name WHERE actual.column_id IS NULL OR actual.system_type_id<>expected.TypeId OR actual.user_type_id<>expected.TypeId OR actual.max_length<>expected.MaxLength OR actual.scale<>expected.Scale OR actual.is_nullable<>expected.Nullable OR (expected.Name=N'WorkTypeName' AND ISNULL(actual.collation_name,N'') COLLATE Latin1_General_100_BIN2<>N'Latin1_General_100_BIN2')) THROW 54926,N'Legacyclaim besitzt nicht die exakte achtspaltige Form.',2;
SELECT CAST('PASS' AS varchar(16)) GenuineQueue20To21Upgrade;
